-- required version
PANDOC_VERSION:must_be_at_least '2.13'


-- global crossref state
crossref = {
  usingTheorems = false,
  startAppendix = nil
}

-- [import]
function import(script)
  local path = PANDOC_SCRIPT_FILE:match("(.*[/\\])")
  dofile(path .. script)
end
import("index.lua")
import("preprocess.lua")
import("sections.lua")
import("figures.lua")
import("tables.lua")
import("equations.lua")
import("listings.lua")
