import("../common/theorems.lua")
import("../common/meta.lua")
import("../common/table.lua")
import("../common/string.lua")
import("../common/debug.lua")
-- [/import]

initIndex()

-- chain of filters
return {
  initCrossrefOptions(),
  preprocess(),
  preprocessTheorems(),
  combineFilters({
    fileMetadata(),
    qmd(),
    sections(),
    figures(),
    tables(),
    equations(),
    listings(),
    theorems(),
  }),
  resolveRefs(),
  crossrefMetaInject(),
  writeIndex()
}

